(async () => {
  const fail = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const learnerId = String(Inputs.learnerId || '').trim();
    const conceptId = String(Inputs.conceptId || '').trim();
    const who = await DOOR.learner(learnerId);
    if (!who) return fail('There is no learner with the id "' + learnerId + '". learnersForLessons lists them.');
    const at = DOOR.stepFor((await DOOR.livePath(learnerId)).steps, conceptId, who.name);
    if (at.why) return fail(at.why);
    const sent = Inputs.lesson;
    if (!sent || typeof sent !== 'object' || Array.isArray(sent)) return fail('Send the lesson as an object with title, hook, landing, steps and sections.');
    const g = DOOR.gate(sent);
    if (g.problems) return fail(DOOR.refusalFor(g.problems));
    const clash = DOOR.fieldClash(g.lesson, await DOOR.fieldsElsewhere(learnerId, conceptId));
    if (clash) return fail(clash);
    const email = await DOOR.callerEmail(Inputs.callerId);
    const existing = (await DOOR.q('LessonDraft', { and: [{ learnerId: { equalTo: learnerId } }, { conceptId: { equalTo: conceptId } }] }, 2))[0];
    let version;
    if (existing) {
      const sentVersion = Inputs.version;
      if (sentVersion === undefined || sentVersion === null || sentVersion === '') {
        return fail('There is already a draft of this lesson (version ' + existing.version + '). Read it with readLesson first; to replace it, send version: ' + existing.version + '.');
      }
      if (Number(sentVersion) !== existing.version) {
        return fail('The draft has changed since you read it: it is now version ' + existing.version + ', and you sent ' + sentVersion + '. Read it again with readLesson.');
      }
      version = existing.version + 1;
      try {
        await Noodl.Records.save(existing.objectId, Object.assign({}, g.lesson, { version, updatedByEmail: email }), { className: 'LessonDraft', ifMatch: { version: existing.version } });
      } catch (e) {
        if (e && e.code === 'precondition-failed') return fail('Someone saved this draft a moment ago. Read it again with readLesson, then send its version.');
        throw e;
      }
    } else {
      version = 1;
      try {
        await Noodl.Records.create('LessonDraft', Object.assign({ learnerId, conceptId }, g.lesson, { version, publishedVersion: null, copiedFromLearnerId: null, updatedByEmail: email }));
      } catch (e) {
        return fail('A draft of this lesson was saved by someone else a moment ago. Read it with readLesson, then send its version.');
      }
    }
    let still = [];
    if (existing && !DOOR.blank(existing.copiedFromLearnerId)) {
      const source = await DOOR.learner(existing.copiedFromLearnerId);
      still = DOOR.mentions(g.lesson, DOOR.leakTerms(source && source.ctx, who.ctx));
    }
    console.log('[dbt:saveLessonDraft] learner=' + learnerId + ' concept=' + conceptId + ' version=' + version);
    Outputs.version = version;
    Outputs.previewPath = DOOR.previewPath(learnerId, conceptId);
    Outputs.stillAboutAnotherLearner = still;
    Outputs.done();
  } catch (e) {
    console.error('[dbt:saveLessonDraft] stopped: ' + String((e && e.message) || e));
    fail('That did not finish, and nothing was half-saved that a second try will not put right. Try again.');
  }
})();
